#include "sector_leader_store.hpp"
#include "sector_observation_restore.hpp"
#include <QtSql>
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QFile>
#include <cstdio>
namespace obs=observationRestore;
int checks=0;
void ck(bool b,const char* why){if(!b)throw std::runtime_error(why);++checks;}
template<class F>void reject(F f,const char*why){bool failed=false;try{f();}catch(const std::exception&){failed=true;}ck(failed,why);}
QByteArray bytes(QString p){QFile f(p);ck(f.open(QIODevice::ReadOnly),"Private file unreadable");return f.readAll();}
void sql(QString file,std::function<void(QSqlDatabase&)> fn){auto name=QUuid::createUuid().toString();{auto db=QSqlDatabase::addDatabase("QSQLITE",name);db.setDatabaseName(file);ck(db.open(),"Private fixture DB unavailable");fn(db);db.close();}QSqlDatabase::removeDatabase(name);}
void seed(QString file,QJsonObject f){sectorLeader::Store store(file);auto packet=f["incoming"].toObject();auto versions=packet["configVersions"].toArray();store.save(versions[0].toObject(),0);store.saveShot(f["currentObservations"].toArray()[0].toObject());store.save(versions[1].toObject(),1);store.saveShot(f["currentObservations"].toArray()[1].toObject());for(int i=2;i<7;i++)store.save(f["currentConfig"].toObject(),i);sql(file,[&](auto&db){auto c=f["currentConfig"].toObject();auto data=QJsonDocument(c).toJson(QJsonDocument::Compact);QSqlQuery q(db);q.prepare("UPDATE config SET revision=?,digest=?,payload=? WHERE id=1");q.addBindValue(7);q.addBindValue(sectorLeader::hash(data));q.addBindValue(data);ck(q.exec(),"Original current fixture fields failed");ck(q.exec("INSERT INTO imports(digest,applied_at) VALUES('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','2026-09-01T00:00:00.123456789Z')"),"Existing config marker fixture failed");});}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{
 QFile input(QString::fromLocal8Bit(argv[1]));ck(input.open(QIODevice::ReadOnly),"Fixture missing");auto f=QJsonDocument::fromJson(input.readAll()).object();QTemporaryDir dir(QString::fromLocal8Bit(argv[2])+"/sql-XXXXXX");ck(dir.isValid(),"Private directory missing");dir.setAutoRemove(false);auto path=dir.filePath("sector.sqlite");seed(path,f);sectorLeader::Store store(path);auto before=store.restoreSnapshot();auto physical=bytes(path);auto p=store.previewRestore(f["incoming"].toObject(),before);ck(store.restoreSnapshot()==before,"Preview changed database state");ck(bytes(path)==physical,"Preview wrote physical database");ck(p["targetObservations"].toArray()==obs::rows(f["expectedObservations"].toArray()),"Original historical fields changed");
 bool cancel=false;reject([&]{store.commitRestore(p,[&]{return cancel;},[&]{cancel=true;});},"Late cancel committed partial batch");ck(store.restoreSnapshot()==before,"Late cancel left config/observations/receipt");ck(bytes(path)==physical,"Rollback left physical DB change");
 auto result=store.commitRestore(p);auto after=store.restoreSnapshot();ck(store.verifyRestore(p,result,after),"Independent store receipt not verified");ck(after["payload"].toObject()["observations"].toArray()==obs::rows(f["expectedObservations"].toArray()),"Actual SQL restore changed original fields");ck(after["restoreState"].toObject()["legacyImports"]==before["restoreState"].toObject()["legacyImports"],"Existing imports markers changed");ck(after["payload"].toObject()["configVersions"].toArray().size()==3,"Complete original configs not retained");
 store.prune("source-board",1,3);auto deleted=store.restoreSnapshot();auto duplicate=store.previewRestore(f["incoming"].toObject(),deleted);ck(duplicate["noChange"].toBool(),"Duplicate source not detected");ck(duplicate["previousReceipt"].toObject()==result,"Original domain receipt changed");ck(store.commitRestore(duplicate)==result,"Repeat did not reuse original receipt");ck(store.restoreSnapshot()==deleted,"Pruned history resurrected");
 auto editedConfig=store.read();auto editedBoards=editedConfig["sectors"].toArray();auto editedBoard=editedBoards[0].toObject();editedBoard["name"]="用户恢复后改名";auto editedLeaders=editedBoard["leaders"].toArray();editedLeaders.removeAt(0);editedBoard["leaders"]=editedLeaders;editedBoards[0]=editedBoard;editedConfig["sectors"]=editedBoards;store.save(editedConfig,qint64(editedConfig["revision"].toDouble()));auto edited=store.restoreSnapshot();auto editedBytes=bytes(path);auto repeatEdited=store.previewRestore(f["incoming"].toObject(),edited);auto originalReceipt=store.commitRestore(repeatEdited);ck(originalReceipt==result,"Repeated newer configuration replaced original receipt");ck(store.verifyRestore(repeatEdited,originalReceipt,edited),"Duplicate original receipt did not verify newer unchanged baseline");ck(store.restoreSnapshot()==edited,"Repeated archive resurrected deleted config members");ck(bytes(path)==editedBytes,"No-change receipt reuse wrote existing file");
 auto freshPath=dir.filePath("cas.sqlite");seed(freshPath,f);sectorLeader::Store cas(freshPath);auto state=cas.restoreSnapshot(),plan=cas.previewRestore(f["incoming"].toObject(),state);auto current=cas.read();cas.save(current,qint64(current["revision"].toDouble()));auto changed=cas.restoreSnapshot();reject([&]{cas.commitRestore(plan);},"Changed current config bypassed CAS");ck(cas.restoreSnapshot()==changed,"CAS rejection changed newer state");
 auto mergePath=dir.filePath("merge.sqlite");seed(mergePath,f);sectorLeader::Store mergeStore(mergePath);auto mergeBefore=mergeStore.restoreSnapshot();auto addPacket=f["incoming"].toObject();auto newConfig=addPacket["config"].toObject();newConfig["revision"]=3;auto boards=newConfig["sectors"].toArray();auto board=boards[0].toObject();auto leaders=board["leaders"].toArray();auto leader=leaders[0].toObject();leader["id"]="new-source-leader";leader["code"]="600001";leader["fullId"]="SH:stock:600001";leaders.append(leader);board["leaders"]=leaders;boards[0]=board;newConfig["sectors"]=boards;addPacket["config"]=newConfig;auto all=addPacket["configVersions"].toArray();all.append(newConfig);addPacket["configVersions"]=all;auto mergePlan=mergeStore.previewRestore(addPacket,mergeBefore);ck(mergePlan["configChanged"].toBool(),"Real config merge plan absent");bool stop=false;reject([&]{mergeStore.commitRestore(mergePlan,[&]{return stop;},[&]{stop=true;});},"Config plus observation batch did not roll back");ck(mergeStore.restoreSnapshot()==mergeBefore,"Late cancel left new config version/history/receipt");auto mergedReceipt=mergeStore.commitRestore(mergePlan);auto mergeAfter=mergeStore.restoreSnapshot();ck(mergeStore.verifyRestore(mergePlan,mergedReceipt,mergeAfter),"Real config merge receipt failed");ck(mergeAfter["payload"].toObject()["config"].toObject()["revision"].toInt()==8,"Original config writer not reused");ck(mergeAfter["payload"].toObject()["configVersions"].toArray().size()==5,"Original/committed config versions missing in database");
 auto malformed=dir.filePath("bad.sqlite");QFile bad(malformed);ck(bad.open(QIODevice::WriteOnly),"Bad fixture unavailable");bad.write("corrupt-preserve-original");bad.close();auto badBytes=bytes(malformed);reject([&]{sectorLeader::Store(malformed).restoreSnapshot();},"Corrupt file adopted");ck(bytes(malformed)==badBytes,"Corrupt file modified/deleted");
 auto foreign=dir.filePath("foreign.sqlite");sql(foreign,[&](auto&db){QSqlQuery q(db);ck(q.exec("CREATE TABLE foreign_data(value TEXT)"),"Foreign fixture failed");ck(q.exec("INSERT INTO foreign_data VALUES('private-original')"),"Foreign fixture data failed");});auto foreignBytes=bytes(foreign);reject([&]{sectorLeader::Store(foreign).restoreSnapshot();},"Foreign database adopted");ck(bytes(foreign)==foreignBytes,"Foreign database changed");
 auto triggerPath=dir.filePath("trigger.sqlite");seed(triggerPath,f);sql(triggerPath,[&](auto&db){QSqlQuery q(db);ck(q.exec("CREATE TRIGGER extra AFTER INSERT ON observations BEGIN DELETE FROM observations; END"),"Trigger fixture failed");});auto triggerBytes=bytes(triggerPath);reject([&]{sectorLeader::Store(triggerPath).restoreSnapshot();},"Unknown trigger accepted");ck(bytes(triggerPath)==triggerBytes,"Unknown-schema file changed");
 auto missing=dir.filePath("missing.sqlite");reject([&]{sectorLeader::Store(missing).restoreSnapshot();},"Missing file created");ck(!QFile::exists(missing),"Missing file boundary violated");
 std::printf("{\"checks\":%d,\"readonlyPreview\":true,\"lateCancelAtomicRollback\":true,\"cas\":true,\"deletedNotResurrected\":true,\"foreignAndCorruptPreserved\":true}\n",checks);return 0;
 }catch(const std::exception&e){std::fprintf(stderr,"%s at check %d\n",e.what(),checks);return 1;}}
